CREATE TABLE InventoryDocuments(Id NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY,Number NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL UNIQUE,Kind NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,State NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,Version BIGINT NOT NULL,CreatedBy NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,ApprovedBy NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,Reason NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,Evidence NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,CreatedAt NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,ReversalOf NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NULL REFERENCES InventoryDocuments(Id),LinesJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL);
CREATE INDEX IX_InventoryDocuments_State ON InventoryDocuments(State,CreatedAt,Id);
CREATE TABLE InventoryDocumentHistory(Id NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY,DocumentId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES InventoryDocuments(Id),Action NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,ActorId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,Reason NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,CreatedAt NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,DataJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL);
CREATE INDEX IX_InventoryDocumentHistory_Doc ON InventoryDocumentHistory(DocumentId,CreatedAt,Id);
CREATE TABLE InventoryMovements(DocumentId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES InventoryDocuments(Id),SkuId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,OnHandDelta BIGINT NOT NULL,QuarantineDelta BIGINT NOT NULL,OnHandAfter BIGINT NOT NULL,QuarantineAfter BIGINT NOT NULL,InventoryVersion BIGINT NOT NULL,QuarantineVersion BIGINT NOT NULL,PRIMARY KEY(DocumentId,SkuId));
CREATE TABLE InventoryReversals(OriginalId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY REFERENCES InventoryDocuments(Id),ReversalId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL UNIQUE REFERENCES InventoryDocuments(Id));
ALTER TABLE InventoryLedger ADD StockDocumentId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NULL REFERENCES InventoryDocuments(Id);
